<?php $title="Test Rides";require "includes/header.php";$r=$conn->query("SELECT t.*,c.name customer,b.name bicycle FROM test_rides t JOIN customers c ON c.id=t.customer_id JOIN bicycles b ON b.id=t.bicycle_id ORDER BY ride_date DESC");?><div class="section-title"><div><h2>🏁 Test Ride Studio</h2><p class="muted">Convert product interest into experience.</p></div><a class="btn primary" href="add_test_ride.php">+ Schedule</a></div><div class="card"><table><tr><th>Customer</th><th>Bicycle</th><th>Date</th><th>Time</th><th>Status</th></tr><?php while($x=$r->fetch_assoc()):?><tr><td><?=e($x["customer"])?></td><td><?=e($x["bicycle"])?></td><td><?=e($x["ride_date"])?></td><td><?=e($x["ride_time"])?></td><td><span class="badge"><?=e($x["status"])?></span></td></tr><?php endwhile;?></table></div><?php require "includes/footer.php";?>